INSERT INTO public.email_templates (name, audience, contexts, subject, body) VALUES
('Guest — we are on it', 'guest', ARRAY['ticket']::text[],
 'Update on your stay at {{property}}',
 E'Hi {{guest_name}},\n\nThanks for letting us know about {{ticket_title}}. We have it in hand and a team member is working on it now.\n\nWe will follow up as soon as we have a time for you. If anything changes in the meantime, just reply to this email.\n\n{{sender_name}}\nA Real Home Away'),
('Guest — visit scheduled', 'guest', ARRAY['ticket','work_order']::text[],
 'Someone is coming to {{property}}',
 E'Hi {{guest_name}},\n\nWe have scheduled a visit for {{scheduled_for}} to take care of {{ticket_title}}.\n\nPlease let us know if that time does not work and we will find another.\n\n{{sender_name}}\nA Real Home Away'),
('Guest — resolved', 'guest', ARRAY['ticket']::text[],
 'All set at {{property}}',
 E'Hi {{guest_name}},\n\nThis is now taken care of. Thank you for your patience while we sorted it out.\n\nIf anything is still not right, reply here and we will come straight back to it.\n\n{{sender_name}}\nA Real Home Away'),
('Homeowner — issue notice', 'owner', ARRAY['ticket','property']::text[],
 '{{property}} — {{ticket_title}}',
 E'Hi {{owner_name}},\n\nWe want to keep you informed about {{property}}. {{ticket_title}} was reported and our team is handling it.\n\nWe will let you know once it is resolved, along with anything that needs your decision.\n\n{{sender_name}}\nA Real Home Away'),
('Homeowner — approval needed', 'owner', ARRAY['work_order','ticket']::text[],
 'Your approval needed at {{property}}',
 E'Hi {{owner_name}},\n\nWe need your go-ahead before we continue with {{work_order_title}} at {{property}}.\n\nDetails and the expected cost are below. Reply to this email with your decision and we will move right away.\n\n{{sender_name}}\nA Real Home Away'),
('Vendor — job brief', 'vendor', ARRAY['work_order','ticket']::text[],
 'Job at {{property}} — {{work_order_title}}',
 E'Hi {{vendor_name}},\n\nWe would like you to take care of the following at {{property}} ({{property_address}}):\n\n{{work_order_title}}\n\nPlease confirm you can take it and let us know when you can be on site. Send photos before and after, and any parts or costs.\n\n{{sender_name}}\nA Real Home Away'),
('Vendor — schedule confirmation', 'vendor', ARRAY['work_order']::text[],
 'Confirming {{scheduled_for}} at {{property}}',
 E'Hi {{vendor_name}},\n\nConfirming your visit to {{property}} on {{scheduled_for}} for {{work_order_title}}.\n\nIf anything changes, reply to this email so we can update the guest and the homeowner.\n\n{{sender_name}}\nA Real Home Away');